/** Camera + landmarker lifecycle hook and the camera stage (video + overlay). */
import type { ComponentChildren } from 'preact';
import { useEffect, useRef, useState } from 'preact/hooks';
import { CONTOURS, assessFrame, type FrameObservation, type FrameQuality } from '../core';
import { cameraLabel, closeCamera, openCamera, startFrameLoop, type CameraError } from '../vision/camera';
import type { FaceEngine } from '../vision/landmarker';

const ERROR_TEXT: Record<CameraError | 'model' | 'integrity', string> = {
  insecure: '카메라는 보안 연결(HTTPS 또는 localhost)에서만 사용할 수 있습니다.',
  unsupported: '이 브라우저는 카메라를 지원하지 않습니다. 최신 Chrome 또는 Safari를 사용하세요.',
  permission: '카메라 권한이 거부되었습니다. 브라우저 설정에서 이 사이트의 카메라를 허용해 주세요.',
  notFound: '전면 카메라를 찾을 수 없습니다.',
  busy: '다른 앱이 카메라를 사용 중입니다. 다른 앱을 닫고 다시 시도하세요.',
  unknown: '카메라를 열 수 없습니다.',
  model: '얼굴 분석 엔진을 불러오지 못했습니다. 네트워크 연결을 확인하고 다시 시도하세요.',
  integrity: '얼굴 인식 모델의 무결성 검증에 실패했습니다. 검증된 모델로 다시 설치해 주세요.',
};

export type CamStatus = 'idle' | 'loading' | 'ready' | 'error';

/** The previous assessment's rest face (keyframe pixels of a width × height image), drawn dashed to line up with. */
export interface Ghost {
  width: number;
  height: number;
  /** Flat x, y pairs for all 478 points. */
  pts: readonly number[];
}

const GHOST_CONTOURS = ['faceOval', 'rightEye', 'leftEye', 'lipsOuter'] as const;

/** A different camera shape would put the outline in the wrong place: the ghost is only drawn when this holds. */
export const ghostFits = (g: Ghost, w: number, h: number): boolean => Math.abs(g.width / g.height - w / h) <= 0.03;

function drawGhost(ctx: CanvasRenderingContext2D, g: Ghost, w: number, h: number): void {
  if (!ghostFits(g, w, h)) return;
  const sx = w / g.width;
  const sy = h / g.height;
  ctx.save();
  ctx.setLineDash([Math.max(4, w / 90), Math.max(4, w / 90)]);
  ctx.strokeStyle = 'rgba(120,190,255,0.9)';
  for (const name of GHOST_CONTOURS) {
    ctx.beginPath();
    CONTOURS[name]!.forEach((i, k) => {
      const x = g.pts[2 * i]! * sx;
      const y = g.pts[2 * i + 1]! * sy;
      if (k) ctx.lineTo(x, y);
      else ctx.moveTo(x, y);
    });
    ctx.stroke();
  }
  ctx.restore();
}

function drawOverlay(canvas: HTMLCanvasElement | null, obs: FrameObservation, q: FrameQuality, ghost: Ghost | null): void {
  if (!canvas) return;
  if (canvas.width !== obs.width || canvas.height !== obs.height) {
    canvas.width = obs.width;
    canvas.height = obs.height;
  }
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.lineWidth = Math.max(1.5, obs.width / 480);
  if (ghost) drawGhost(ctx, ghost, obs.width, obs.height);
  const lm = obs.landmarks;
  if (lm.length < 468 * 3) return;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = q.ok ? 'rgba(255,255,255,0.8)' : 'rgba(250,178,25,0.95)';
  for (const c of Object.values(CONTOURS)) {
    ctx.beginPath();
    c.forEach((i, k) => {
      const x = lm[3 * i]! * obs.width;
      const y = lm[3 * i + 1]! * obs.height;
      if (k) ctx.lineTo(x, y);
      else ctx.moveTo(x, y);
    });
    ctx.stroke();
  }
}

/**
 * `onFrame` also gets the video element, still showing the detected frame (for landmark tracking). `ghost`, when set,
 * is drawn dashed under the live outline (the previous assessment's face position).
 */
export function useFaceCamera(
  active: boolean,
  onFrame?: (obs: FrameObservation, q: FrameQuality, src: HTMLVideoElement) => void,
  ghost: Ghost | null = null,
) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const engineRef = useRef<FaceEngine | null>(null);
  const cb = useRef(onFrame);
  cb.current = onFrame;
  const ghostRef = useRef(ghost);
  ghostRef.current = ghost;
  const [status, setStatus] = useState<CamStatus>('idle');
  const [message, setMessage] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [quality, setQuality] = useState<FrameQuality | null>(null);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    if (!active) return;
    let stop = () => {};
    let cancelled = false;
    setStatus('loading');
    setError(null);
    (async () => {
      let engine: FaceEngine;
      try {
        // Lazy-loaded: the ML runtime is only fetched when the camera is first used.
        const { getEngine } = await import('../vision/landmarker');
        engine = await getEngine(setMessage);
      } catch (e) {
        if (cancelled) return;
        setError(String(e).includes('MODEL_INTEGRITY') ? ERROR_TEXT.integrity : ERROR_TEXT.model);
        setStatus('error');
        return;
      }
      if (cancelled || !videoRef.current) return;
      engineRef.current = engine;
      setMessage('카메라 여는 중…');
      try {
        const stream = await openCamera(videoRef.current);
        if (cancelled) return closeCamera(stream);
        streamRef.current = stream;
      } catch (e) {
        if (cancelled) return;
        setError(ERROR_TEXT[((e as { code?: CameraError }).code ?? 'unknown') as CameraError]);
        setStatus('error');
        return;
      }
      setStatus('ready');
      let n = 0;
      const video = videoRef.current;
      stop = startFrameLoop(video, engine, (obs) => {
        const q = assessFrame(obs);
        drawOverlay(canvasRef.current, obs, q, ghostRef.current);
        cb.current?.(obs, q, video);
        if (++n % 4 === 0) setQuality(q);
      });
    })();
    return () => {
      cancelled = true;
      stop();
      closeCamera(streamRef.current);
      streamRef.current = null;
      setStatus('idle');
    };
  }, [active, attempt]);

  return {
    videoRef,
    canvasRef,
    status,
    message,
    error,
    quality,
    engine: () => engineRef.current,
    cameraLabel: () => cameraLabel(streamRef.current),
    retry: () => setAttempt((a) => a + 1),
  };
}

export function CameraStage({ cam, children }: { cam: ReturnType<typeof useFaceCamera>; children?: ComponentChildren }) {
  return (
    <div class="stage">
      <video ref={cam.videoRef} class="mirror" playsInline muted autoPlay />
      <canvas ref={cam.canvasRef} class="mirror" />
      {cam.status !== 'ready' && (
        <div class="placeholder">
          {cam.status === 'error' ? (
            <div class="stack">
              <div>{cam.error}</div>
              <button class="btn sm" onClick={cam.retry}>
                다시 시도
              </button>
            </div>
          ) : (
            <div>{cam.message || '준비 중…'}</div>
          )}
        </div>
      )}
      {cam.status === 'ready' && children}
    </div>
  );
}

let wakeLock: { release: () => Promise<void> } | null = null;

/** Keep the screen on during capture (best effort). */
export function useWakeLock(on: boolean): void {
  useEffect(() => {
    if (!on) return;
    const nav = navigator as Navigator & { wakeLock?: { request: (t: 'screen') => Promise<{ release: () => Promise<void> }> } };
    nav.wakeLock
      ?.request('screen')
      .then((l) => (wakeLock = l))
      .catch(() => undefined);
    return () => {
      wakeLock?.release().catch(() => undefined);
      wakeLock = null;
    };
  }, [on]);
}

export function speak(text: string, enabled: boolean): void {
  if (!enabled || typeof speechSynthesis === 'undefined') return;
  speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = 'ko-KR';
  u.rate = 1.05;
  speechSynthesis.speak(u);
}
